import {regions} from './coastal-geography.js';
import {countryLearning,unlockedCountries,flagUrl,countryQuestions,answerGeographyCoin} from './coastal-learning.js';
export function installLearningUI({root,map,side,state,node,refresh}){
 function flag(id){const image=node('img',null,'coastal-country-flag');image.src=flagUrl(id);image.alt=id==='northern-ireland'?'Union Flag of the United Kingdom':regions.find(r=>r.id===id).name+' flag';return image;}
 function modal(label,cls){const dialog=node('dialog',null,'coastal-shop '+cls),close=node('button','Close '+label.toLowerCase()+' ×');close.type='button';close.onclick=()=>dialog.close();dialog.setAttribute('aria-label',label);dialog.append(close);root.append(dialog);return dialog;}
 const atlas=modal('Atlas','coastal-country-shop'),nav=node('nav',null,'coastal-country-nav'),content=node('article',null,'coastal-country-content');nav.setAttribute('aria-label','Unlocked countries');atlas.append(node('h3','Your geography atlas'),node('p','Explore the countries you have unlocked. Play pauses while you read.'),nav,content);let resumeAtlas=false;
 function showCountry(id){const r=unlockedCountries(state.round).find(r=>r.id===id);if(!r)return;const d=countryLearning[id];for(const b of nav.children)b.setAttribute('aria-pressed',String(b.dataset.country===id));const banner=node('header',null,'coastal-country-banner'),title=node('div');title.append(node('h3',r.name),node('strong','Capital · '+r.capital),node('p',d.setting));banner.append(flag(id),title);content.replaceChildren(banner);if(d.flagNote)content.append(node('p',d.flagNote,'coastal-flag-note'));content.append(node('h4','Landmarks to remember'));const sights=node('div',null,'coastal-landmark-grid');for(const [name,location,description,icon]of d.landmarks){const card=node('section',null,'coastal-landmark-card');card.append(node('span',icon,'coastal-landmark-icon'),node('h4',name),node('strong',location),node('p',description));sights.append(card);}content.append(sights,node('h4','Waterways'),node('p',d.water),node('h4','Interesting facts'));const facts=node('ul');for(const fact of [...r.facts,...d.extra])facts.append(node('li',fact));content.append(facts);const source=node('a','Explore official destination information ↗');source.href=d.source??r.source;source.target='_blank';source.rel='noopener';content.append(source);}
 function openAtlas(id,resume=state.running){resumeAtlas=resume;state.running=false;nav.replaceChildren();for(const r of unlockedCountries(state.round)){const b=node('button',r.name);b.type='button';b.dataset.country=r.id;b.prepend(flag(r.id));b.onclick=()=>showCountry(r.id);nav.append(b);}showCountry(id??unlockedCountries(state.round).at(-1).id);refresh();atlas.showModal();}
 atlas.addEventListener('close',()=>{if(resumeAtlas&&!state.complete&&!state.failed)state.running=true;resumeAtlas=false;refresh();});
 const atlasButton=node('button','🌍 Country atlas','coastal-atlas-button');atlasButton.type='button';atlasButton.onclick=()=>openAtlas();side.append(atlasButton);
 const coin=node('button','🪙','coastal-quiz-coin');coin.type='button';coin.hidden=true;coin.setAttribute('aria-label','Geography quiz coin · earn 15 credits');coin.title='Geography question · +15 credits';map.append(coin);
 const quiz=modal('Quiz','coastal-quiz-shop'),quizContent=node('div');quiz.append(quizContent);let resumeQuiz=false;
 coin.onclick=()=>{const token=state.learning.coin;if(!token)return;resumeQuiz=state.running;state.running=false;const r=regions.find(r=>r.id===token.region),q=countryQuestions(token.region)[token.question];quizContent.replaceChildren(flag(r.id),node('p',r.name+' · Geography bonus','coastal-eyebrow'),node('h3',q.prompt),node('p','One answer · Correct = +15 credits. No penalty for an incorrect answer.'));const choices=node('div',null,'coastal-quiz-answers'),result=node('div',null,'coastal-quiz-result');result.setAttribute('role','status');const options=q.options.map((value,i)=>({value,rank:(i+token.id)%q.options.length})).sort((a,b)=>a.rank-b.rank);for(const {value}of options){const b=node('button',value);b.type='button';b.onclick=()=>{const answer=answerGeographyCoin(state,token.id,value);if(!answer)return;for(const option of choices.children){option.disabled=true;option.dataset.correct=String(option.textContent===answer.answer);}b.dataset.chosen='true';result.replaceChildren(node('strong',answer.correct?'Great geography! +15 credits':'Keep exploring! The answer is '+answer.answer+'.'),node('p',answer.explanation));const learn=node('button','Explore '+r.name+' in your atlas');learn.type='button';learn.onclick=()=>{const resume=resumeQuiz;resumeQuiz=false;quiz.close();openAtlas(r.id,resume);};result.append(learn);refresh();};choices.append(b);}quizContent.append(choices,result);refresh();quiz.showModal();};
 quiz.addEventListener('close',()=>{if(resumeQuiz&&!state.complete&&!state.failed)state.running=true;resumeQuiz=false;refresh();});
 return {refresh(){const token=state.learning.coin;coin.hidden=!token||state.complete||state.failed;coin.style.left=(token?.x??50)+'%';coin.style.top=(token?.y??35)+'%';atlasButton.textContent='🌍 Country atlas · '+unlockedCountries(state.round).length+' unlocked';}};
}
